begin;select no_plan();
select has_table('public','statements','statements exist');select has_table('public','statement_lines','immutable lines exist');
select has_table('public','reconciliation_sessions','sessions exist');select has_table('public','reconciliation_items','items exist');
select has_table('public','reconciliation_adjustments','adjustments exist');select has_table('public','close_checklists','checklists exist');
select has_table('public','reconciliation_status_events','status history exists');
select has_function('public','keel_statement_create',array['uuid','text','jsonb','uuid','jsonb'],'statement command exists');
select has_function('public','keel_reconciliation_close',array['uuid','text','jsonb','uuid','jsonb'],'close exists');
select has_function('public','keel_reconciliation_reopen',array['uuid','text','jsonb','uuid','jsonb'],'reopen exists');
select is((select r.rolname from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='public.keel_reconciliation_close(uuid,text,jsonb,uuid,jsonb)'::regprocedure),'keel_api','close owner');
insert into public.canonical_transactions(id,household_id,entity_id,account_id,status,source,description,effective_date,economic_event_key)values('a8000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-00000000a001','00000000-0000-4000-8000-00000000a101','00000000-0000-4000-8000-00000000a401','posted','manual','statement deposit','2026-06-15','pgtap:statement:deposit');
insert into public.journal_batches(id,household_id,canonical_transaction_id,description,effective_date,command_id)values('a8000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-00000000a001','a8000000-0000-4000-8000-000000000001','statement deposit','2026-06-15','a8000000-0000-4000-8000-000000000021');
insert into public.journal_postings(id,batch_id,ledger_account_id,entity_id,amount_minor,currency)values('a8000000-0000-4000-8000-000000000031','a8000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-00000000a301','00000000-0000-4000-8000-00000000a101',120,'USD'),('a8000000-0000-4000-8000-000000000032','a8000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-00000000a318','00000000-0000-4000-8000-00000000a101',-120,'USD');
set local role authenticated;set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}';
select lives_ok($$select public.keel_statement_create('a8000000-0000-4000-8000-000000000041','pgtap:statement:create','{}','00000000-0000-4000-8000-00000000a001',jsonb_build_object('account_id','00000000-0000-4000-8000-00000000a401','period_start','2026-06-01','period_end','2026-06-30','opening_minor','100','ending_minor','120','currency','USD','source_hash',repeat('c',64),'lines',jsonb_build_array(jsonb_build_object('line_key','deposit','date','2026-06-15','amount_minor','20','description','deposit'))))$$,'statement source captured');
select lives_ok($$select public.keel_reconciliation_close('a8000000-0000-4000-8000-000000000042','pgtap:reconcile:close','{}','00000000-0000-4000-8000-00000000a001',jsonb_build_object('statement_id',(select id from public.statements limit 1),'items',jsonb_build_array(jsonb_build_object('line_id',(select id from public.statement_lines limit 1),'resolution','matched_transaction','transaction_id','a8000000-0000-4000-8000-000000000001','explanation','matched')),'adjustments','[]'::jsonb))$$,'every line explained and difference zero closes');
select is((select status::text from public.reconciliation_sessions limit 1),'closed','session closed');select is((select count(*)::int from public.period_locks where reopened_at is null),1,'close locks history');
select is(public.keel_list_statements('00000000-0000-4000-8000-00000000a001')->'rows'->0->'session'->'items'->0->>'explanation','matched','read proof includes close evidence');
select lives_ok($$select public.keel_reconciliation_reopen('a8000000-0000-4000-8000-000000000043','pgtap:reconcile:reopen','{}','00000000-0000-4000-8000-00000000a001',jsonb_build_object('session_id',(select id from public.reconciliation_sessions limit 1),'reason','correction'))$$,'reopen is explicit and reversible');
select ok((select reopened_at is not null and reopen_reason='correction' from public.period_locks limit 1),'lock reopened with reason');reset role;
select throws_ok($$update public.statements set ending_minor=1$$,'P0001',null,'statement source immutable');select throws_ok($$update public.statement_lines set amount_minor=1$$,'P0001',null,'source lines immutable');select throws_ok($$delete from public.reconciliation_items$$,'P0001',null,'explanations append-only');
select ok((select before is not null and after is not null from public.audit_log where action='reconciliations.reopen'),'reopen audited');select * from finish();rollback;
